import 'dart:math';
import 'dart:ui' show PointMode;

import 'package:flutter/material.dart';

import '../theme.dart';

/// Dot-matrix world map with the exit location marked. Coastlines are coarse
/// hand-made polygons rasterised to a 2° grid.
class WorldMap extends StatelessWidget {
  const WorldMap({super.key, this.lat, this.lon, this.label});
  final double? lat, lon;
  final String? label;

  @override
  // Its own layer: a few thousand dots that only change with the exit IP.
  Widget build(BuildContext context) => RepaintBoundary(child: CustomPaint(painter: _MapPainter(lat, lon, label), size: Size.infinite));
}

class _MapPainter extends CustomPainter {
  _MapPainter(this.lat, this.lon, this.label);
  final double? lat, lon;
  final String? label;

  static List<Offset>? _dots;

  static List<Offset> get dots => _dots ??= _raster();

  @override
  void paint(Canvas canvas, Size size) {
    // Window in degrees, centred on the exit when known.
    const spanLon = 160.0;
    final spanLat = spanLon * size.height / size.width;
    final cLon = (lon ?? 100).clamp(-180 + spanLon / 2, 180 - spanLon / 2);
    final cLat = (lat ?? 20).clamp(-56 + spanLat / 2, 80 - spanLat / 2);
    final left = cLon - spanLon / 2, top = cLat + spanLat / 2;
    final k = size.width / spanLon;
    Offset proj(double lo, double la) => Offset((lo - left) * k, (top - la) * k);

    final paint = Paint()
      ..color = const Color(0xFF34343A)
      ..strokeCap = StrokeCap.round
      ..strokeWidth = max(2.0, k * 1.15);
    final pts = <Offset>[];
    for (final d in dots) {
      final p = proj(d.dx, d.dy);
      if (p.dx >= -2 && p.dy >= -2 && p.dx <= size.width + 2 && p.dy <= size.height + 2) pts.add(p);
    }
    canvas.drawPoints(PointMode.points, pts, paint);

    if (lat == null || lon == null) return;
    final c = proj(lon!, lat!);
    canvas.drawCircle(c, 14, Paint()..color = SF.accent.withValues(alpha: .10));
    canvas.drawCircle(
        c,
        7.5,
        Paint()
          ..style = PaintingStyle.stroke
          ..strokeWidth = .9
          ..color = SF.accent.withValues(alpha: .55));
    canvas.drawCircle(c, 3, Paint()..color = SF.accent);
    if (label != null) {
      final tp = TextPainter(text: TextSpan(text: label, style: SF.t(11, weight: FontWeight.w500)), textDirection: TextDirection.ltr)..layout();
      tp.paint(canvas, c + Offset(12, -tp.height / 2 - 1));
    }
  }

  @override
  bool shouldRepaint(_MapPainter old) => old.lat != lat || old.lon != lon || old.label != label;

  static bool _in(double x, double y, List<double> p) {
    var c = false;
    for (var i = 0, j = p.length - 2; i < p.length; j = i, i += 2) {
      final xi = p[i], yi = p[i + 1], xj = p[j], yj = p[j + 1];
      if ((yi > y) != (yj > y) && x < (xj - xi) * (y - yi) / (yj - yi) + xi) c = !c;
    }
    return c;
  }

  static List<Offset> _raster() {
    List<double> box(List<double> p) {
      var a = 180.0, b = 90.0, c = -180.0, d = -90.0;
      for (var i = 0; i < p.length; i += 2) {
        a = min(a, p[i]);
        c = max(c, p[i]);
        b = min(b, p[i + 1]);
        d = max(d, p[i + 1]);
      }
      return [a, b, c, d];
    }

    final land = [for (final p in _land) (p, box(p))];
    final water = [for (final p in _water) (p, box(p))];
    bool hit(List<(List<double>, List<double>)> l, double x, double y) =>
        l.any((o) => x >= o.$2[0] && x <= o.$2[2] && y >= o.$2[1] && y <= o.$2[3] && _in(x, y, o.$1));
    final out = <Offset>[];
    for (var la = 79.0; la >= -55; la -= 2) {
      for (var lo = -179.0; lo <= 179; lo += 2) {
        if (hit(land, lo, la) && !hit(water, lo, la)) out.add(Offset(lo, la));
      }
    }
    return out;
  }
}

